import{_ as t,o,c as n,a2 as i}from"./chunks/framework.BXzK3EA4.js";const a="/assets/36805aca49ed6468.DQoKTDHo.png",s="/assets/aec5bf5016c43af0.BCChVa8P.png",r="/assets/0064da179de1d490.nsGuIDrM.png",l="/assets/430b8763338b8d11.DZgGlOiy.png",c="data:image/png;base64,",d="/assets/5a50422c0dcb2a46.VBwS9NHK.png",I=JSON.parse('{"title":"How to configure multiple IP addresses in CentOS operating system","description":"","frontmatter":{"title":"How to configure multiple IP addresses in CentOS operating system"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/linux/how-to-configure-multiple-ip-addresses-in-centos-operating-system.md","filePath":"operations-knowledge-base/operating-system/linux/how-to-configure-multiple-ip-addresses-in-centos-operating-system.md","lastUpdated":1794311093000}'),u={name:"operations-knowledge-base/operating-system/linux/how-to-configure-multiple-ip-addresses-in-centos-operating-system.md"};function p(h,e,f,m,g,w){return o(),n("div",null,[...e[0]||(e[0]=[i('<ol><li>You can use the &quot;Linux_tools.sh&quot; script to automatically add multiple IP addresses.</li></ol><ul><li>Download and install the script using the following link：<a href="/operations-knowledge-base/operating-system/">system tools</a></li></ul><p><img src="'+a+'" alt=""></p><p>Usage Instructions:</p><ul><li>At any prompt, enter 0 to return to the menu. By default, the script will be automatically deleted upon exit. However, in some cases, manual deletion may be required if the script fails.</li></ul><p>IP Configuration Function:</p><ul><li>The IP configuration function supports CentOS 6-8, Ubuntu 14-22, and Debian systems. Both block IP configuration and sequential IP configuration must strictly follow the example provided.</li><li>If there is only one network interface in the system that is in an UP state, the IP will be configured on that interface by default. If there are multiple network interfaces in an UP state, you can select the interface to configure the IP.</li><li>When configuring IP on CentOS, simply press Enter to configure the IP in the main network configuration file. If you choose to configure it in range format, it may take longer to take effect, and there may be a timeout when executing the network service restart command. In reality, the configuration is already taking effect gradually, so please avoid repeating the network service restart command.</li><li>In Ubuntu systems, there may be errors when restarting the network service. If you have checked the configuration file and found no issues (usually alignment issues in the configuration file), you can simply reboot the system to apply the changes.</li><li>If you have any questions, enter 9 to view the help menu.</li></ul><ol start="2"><li>Manual Configuration:</li></ol><p>1.First, you need to confirm the network interface name.</p><p>You can use the command &quot;ip a&quot; to check the status of the network interfaces and see the existing IP configurations on your machine. This will help you determine which network interface you want to configure with the multiple IPs.</p><ul><li><p>Check the network interface name: eth0</p></li><li><p>Check the previous IP configurations on eth0</p></li><li><p>Ensure that the network interface is in the UP state, indicating that it is open and connected to the network.</p></li></ul><p><img src="'+s+'" alt=""></p><p>2.Primary Network Interface IP Configuration</p><p>Execute: <code>cd /etc/sysconfig/network-scripts/</code> to enter the directory of network interface configuration files.</p><p>To list the files in the directory, execute the command: <code>ls</code></p><p><img src="'+r+'" alt=""></p><p>To edit the network interface configuration file for eth0, you can use either of the following commands:</p><ol><li>Absolute path command: <code>vi ifcfg-eth0</code> This command will open the network interface configuration file for editing.</li><li>Relative path command: <code>vi /etc/sysconfig/network-scripts/ifcfg-eth0</code> This command will also open the network interface configuration file for editing.</li></ol><p>To configure a range of /29 IP addresses (5 addresses in total), with the numbers 1, 2, 3, 4, and 5 representing the order of the IP addresses, and a single gateway entry, you can follow these steps:</p><p>After entering the network interface configuration file, press <code>a</code> to enter insert mode. Use the arrow keys to move to the last line and add the desired configuration. Press <code>ESC</code> to exit the insert mode and return to command mode. Finally, press <code>:wq</code> to save the changes and exit the editor.</p><p>Press <code>Shift+:</code> to enter the command mode. Then type <code>wq</code> to save the changes and exit the editor. Press Enter to confirm.</p><ul><li><p>IPADDR=Please write the assigned IP addresses.</p></li><li><p>NETMASK=Subnet mask for IP allocation.</p></li><li><p>GATEWAY=Gateway for IP allocation.</p></li></ul><p><img src="'+l+'" alt=""></p><p>3.Restart the network interface for the configuration to take effect.</p><p>Execute the command：systemctl restart network</p><p>4.Additional network interface IP configuration</p><p>For additional network interface IP configuration, you need to create a new subinterface configuration file in the /etc/sysconfig/network-scripts/ directory. The file should be named &quot;range&quot;, and if you are configuring a range of 4 IPs (4*/26) or 8 IPs (8*/27), each segment of IPs can have its own &quot;range&quot; file.</p><p>The files should be named as range0, range1, range2, range3, and so on, in sequential order.</p><p>You can use either of the following commands to create a configuration file for adding a /29 segment:</p><ol><li>Absolute path command: <code>vi /etc/sysconfig/network-scripts/ifcfg-eth0-range0</code></li><li>Relative path command: <code>ifcfg-eth0-range0</code></li></ol><p><img src="'+c+'" alt=""></p><p>The configuration commands are as follows:</p><ul><li>IPADDR_START= Start IP address</li><li>IPADDR_END= End IP address</li><li>PREFIX=29 Subnet mask</li><li>CLONENUM_START=0 Subnet start address</li></ul><p>After entering the network card configuration file, press &quot;a&quot; to enter the insert mode and add the desired configuration. Then press &quot;ESC&quot; to exit the insert mode. Finally, type &quot;:&quot; followed by &quot;wq&quot; to save and exit the file. Press Enter to confirm.</p><p><img src="'+d+'" alt=""></p><p>5.Restart the network card to apply the configuration changes.</p><p>Execute the command：systemctl restart network</p><p>If neither of the above methods work and the configuration changes do not take effect, please contact technical support by submitting a ticket for assistance.</p>',38)])])}const y=t(u,[["render",p]]);export{I as __pageData,y as default};
